def smallest_change(arr):
    def is_palindromic(sub_arr):
        return sub_arr == sub_arr[::-1]

    def count_modifications(sub_arr):
        modifications = 0
        left, right = 0, len(sub_arr) - 1
        while left < right:
            if sub_arr[left] != sub_arr[right]:
                modifications += 1
            left += 1
            right -= 1
        return modifications

    if is_palindromic(arr):
        return 0

    min_modifications = float('inf')
    for i in range(len(arr)):
        sub_arr = arr[:i] + arr[i+1:]
        min_modifications = min(min_modifications, count_modifications(sub_arr))

    return min_modifications

